UPDATE companies SET description='Founded in 1996 in Conway, Arkansas, Sinco Inc. operates as a contract metal manufacturer serving a diverse range of end markets.

Sinco provides sheet metal fabrication services including laser profiling, brake press forming, MIG/TIG/spot and aluminum spool welding, CNC milling and tube cutting, powder coating on two conveyor lines, and assembly. The 115,000-square-foot facility employs over 75 people and runs an electronic Kanban system for just-in-time inventory management and same-day delivery.

The company serves industries such as automotive machinery, supply chain equipment, irrigation infrastructure, industrial machinery, consumer retail, and hospitality.

Sinco differentiates itself through ISO 9001:2015 certification, Six Sigma and Toyota Kata continuous improvement practices, weekly performance metric reviews, and Certified Welding Inspectors on staff. An expedited ''Hot'' job process accommodates urgent deadlines, while a dedicated supply chain team works to maintain competitive pricing.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Laser profiling", "Brake press forming", "MIG welding", "TIG welding", "Spot welding", "Aluminum spool welding", "CNC milling", "CNC tube cutting", "Powder coating (conveyor line)", "Assembly", "Just-in-time inventory management (Kanban)", "Packaging"], "industries": ["Automotive machinery", "Supply chain equipment", "Irrigation infrastructure", "Industrial machinery", "Consumer retail", "Hospitality"], "materials": ["Aluminum", "Steel"], "equipment": ["CNC milling machines", "CNC tube cutting machines", "Brake presses", "MIG/TIG/Spot welding equipment", "Aluminum spool welding equipment", "Two conveyor-driven powder coating lines with multi-stage wash system", "Online sandblasting system", "Preheat ovens", "Cure ovens", "Infrared heating systems"], "volume": "", "lead_time": "Same-day delivery via Kanban system; expedited ''Hot'' job process for urgent orders", "tolerances": "", "built_on": ["ISO 9001:2015 certification with weekly performance assessments", "Six Sigma and Toyota Kata continuous improvement methodologies", "Electronic Kanban system enabling same-day delivery and JIT inventory", "Certified Welding Inspectors (CWIs) on staff", "Expedited ''Hot'' job process for urgent deadlines"], "facts_used": ["Founded 1996 -> /about", "Conway, Arkansas headquarters -> db", "ISO 9001:2015 certified -> /", "Over 75 employees -> /about", "115,000 sq ft facility -> /about", "Capabilities: profiling, forming, welding, machining, powder coating, assembly, inventory management -> /", "Industries: automotive machinery, supply chain, irrigation infrastructure, in